using System.IO.Compression;
using System.Text.Json;
using System.Text.Json.Nodes;
using Orbit.Core;
static class UpgradeChecks {
 public static int Run(string root,bool live=false){try{RunAsync(root,live).GetAwaiter().GetResult();return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static async Task RunAsync(string root,bool live){root=Path.Combine(root,"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Console.WriteLine("TEST ROOT "+root);int count=0;void Check(bool condition,string label){if(!condition)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}void Reject(Action action,string label){try{action();}catch(InvalidDataException){Check(true,label);return;}throw new Exception("Expected rejection: "+label);}
 var settings=new LauncherSettings();Check(settings.Language=="en","New profile defaults to English");settings.Language="ru";settings.GameWidth=1600;settings.GameHeight=900;settings.Fullscreen=true;settings.MinimizeOnLaunch=true;settings.ScrollLog=false;settings.Save(Path.Combine(root,"settings"));var loaded=LauncherSettings.Load(Path.Combine(root,"settings"));Check(loaded.Language=="ru"&&loaded.GameWidth==1600&&loaded.GameHeight==900&&loaded.Fullscreen&&loaded.MinimizeOnLaunch&&!loaded.ScrollLog,"Language and new launch options persist");
 Localization.Language="en";Check(Localization.T("Настройки")=="Settings","English labels");Check(Localization.T("Шаблоны скинов")=="Skin presets","New skin labels translated");Localization.Language="ru";Check(Localization.T("Настройки")=="Настройки","Russian language preserved");Localization.Language="en";
 foreach(var path in new[]{"../bad.jar","/bad.jar","C:/bad.jar","mods/../../bad.jar","mods\\bad.jar","versions/test.json","runtime/a",".orbit-pack.json","mods/CON.jar","mods/a. ","mods/a:stream"})Reject(()=>Modpacks.ContentPath(root,path),"Reject unsafe path: "+path);
 Check(Modpacks.ContentPath(root,"mods/a.jar")==Path.Combine(root,"mods","a.jar"),"Normal mod path accepted");
 foreach(var url in new[]{"http://cdn.modrinth.com/a.jar","https://127.0.0.1/a","https://github.com.evil.invalid/a","https://x@cdn.modrinth.com/a"})Reject(()=>Modpacks.AllowedUri(url),"Reject untrusted pack URL");
 var index=JsonNode.Parse("""{"formatVersion":1,"game":"minecraft","name":"Fixture","dependencies":{"minecraft":"1.21.1","fabric-loader":"0.16.14"},"files":[]}""")!;
 var file=new JsonObject{["path"]="mods/test.jar",["hashes"]=new JsonObject{["sha512"]=new string('a',128)},["fileSize"]=10,["downloads"]=new JsonArray("https://cdn.modrinth.com/a.jar")};index["files"]!.AsArray().Add(file);index["files"]!.AsArray().Add(new JsonObject{["path"]="mods/server.jar",["env"]=new JsonObject{["client"]="unsupported"}});
 var parsed=Modpacks.ParseIndex(index);Check(parsed.Files.Count==1&&parsed.Loader=="fabric-loader"&&parsed.Minecraft=="1.21.1","MRPACK loader and client environment");var duplicate=index.DeepClone();duplicate["files"]!.AsArray().Add(file.DeepClone());Reject(()=>Modpacks.ParseIndex(duplicate),"Duplicate paths rejected");var badhash=index.DeepClone();badhash["files"]![0]!["hashes"]!["sha512"]="bad";Reject(()=>Modpacks.ParseIndex(badhash),"Pack file hash required");var multi=index.DeepClone();multi["dependencies"]!["forge"]="47.1.0";Reject(()=>Modpacks.ParseIndex(multi),"Conflicting loaders rejected");var unknown=index.DeepClone();unknown["dependencies"]!["unknown-loader"]="1";Reject(()=>Modpacks.ParseIndex(unknown),"Unknown loader rejected");
 string archive=Path.Combine(root,"overrides.mrpack");using(var zip=ZipFile.Open(archive,ZipArchiveMode.Create)){foreach(var (name,text) in new[]{("overrides/config/example.txt","common"),("client-overrides/config/example.txt","client"),("server-overrides/config/server.txt","server")}){using var w=new StreamWriter(zip.CreateEntry(name).Open());w.Write(text);}}
 string dest=Path.Combine(root,"override-target");Modpacks.ExtractOverrides(archive,dest);Check(File.ReadAllText(Path.Combine(dest,"config/example.txt"))=="client","Client overrides win over shared overrides");Check(!File.Exists(Path.Combine(dest,"config/server.txt")),"Server overrides not installed on client");string traversal=Path.Combine(root,"bad.mrpack");using(var zip=ZipFile.Open(traversal,ZipArchiveMode.Create)){using var w=new StreamWriter(zip.CreateEntry("overrides/../escape").Open());w.Write("bad");}Reject(()=>Modpacks.ExtractOverrides(traversal,dest),"Archive traversal rejected");
 string presets=Path.Combine(root,"presets");byte[] png=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAEAAAABACAYAAACqaXHeAAAAF0lEQVR42u3BAQ0AAADCoPdPbQ43oAAAAAAAAOA3AsAAAXXVA6kAAAAASUVORK5CYII=");
 // Use the application's own real PNG validation rather than changing current user skin.
 var a=SkinPresets.Save("Test Steve","classic",png,presets);var b=SkinPresets.Save("Test Alex","slim",png,presets);Check(SkinPresets.List(presets).Count==2,"Independent named presets stored");Check(SkinPresets.List(presets).Single(p=>p.Id==b.Id).Model=="slim","Arm model retained per preset");SkinPresets.Delete(a.Id,presets);Check(SkinPresets.List(presets).Count==1&&File.Exists(SkinPresets.Image(b.Id,presets)),"Deleting one preset preserves another");Reject(()=>SkinPresets.Image("../bad",presets),"Preset path validation");
 string failedPacks=Path.Combine(root,"failed-packs");using(var fake=new Modpacks(new BadArchiveHandler(),failedPacks)){bool rejected=false;try{await fake.InstallAsync(new ModProject("fixture","fixture","Fixture","","",0,Array.Empty<string>()));}catch(IOException){rejected=true;}Check(rejected&&Modpacks.Scan(failedPacks).Count==0&&!Directory.GetDirectories(failedPacks).Any(),"Bad archive hash rolls back and publishes no instance");}
 Check(Versions.Scan(Path.Combine(root,"nonexistent")).Count==0,"Clean machine without .minecraft scans safely");
 if(live){using var client=new ModrinthClient();var found=await client.SearchAsync("Simply Optimized","",null,"",0,"relevance",projectType:"modpack");var project=found.Projects.First(p=>p.Slug=="simply-optimized-reloaded");Check(true,"Live Modrinth modpack search with no local version");using var packs=new Modpacks(installRoot:Path.Combine(root,"live-packs"));var entry=await packs.InstallAsync(project,new Progress<ModProgress>(p=>{if(p.Total>0)Console.WriteLine($"PACK {p.Stage}: {p.Done}/{p.Total}");}));Check(entry.RootOverride!=null&&Directory.Exists(Path.Combine(entry.RootOverride,"mods")),"Live MRPACK installed in separate game root");Check(Modpacks.Scan(Path.Combine(root,"live-packs")).Any(p=>p.Id==entry.Id),"Installed pack published to library");var plan=LaunchEngine.Build(new LauncherSettings{GameRoot=entry.RootOverride!,Nickname="OrbitTester"},entry.Id);Check(plan.Missing.Count==0,"Live pack runtime and loader complete without game launch");Check(LaunchEngine.CheckAssets(new LauncherSettings{GameRoot=entry.RootOverride!},plan).Count==0,"Live pack assets complete");File.WriteAllText(Path.Combine(root,"live-pack-result.json"),JsonSerializer.Serialize(entry));}
 Console.WriteLine($"PASS {count} upgrade checks. Minecraft not launched.");
 }
 sealed class BadArchiveHandler:HttpMessageHandler {protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){string json="[{\"id\":\"release\",\"status\":\"listed\",\"version_type\":\"release\",\"files\":[{\"filename\":\"fixture.mrpack\",\"size\":4,\"url\":\"https://cdn.modrinth.com/fixture.mrpack\",\"hashes\":{\"sha512\":\""+new string('0',128)+"\"}}]}]";return Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=request.RequestUri!.Host=="api.modrinth.com"?new StringContent(json):new ByteArrayContent(new byte[]{1,2,3,4})});}}

}
